mapper.select:
SELECT r.id, r.advisor_id, a.name AS advisor_name, r.student_id, s.name AS student_name, r.created_at
FROM advisor_student_relation r
JOIN sys_user a ON a.id = r.advisor_id
JOIN sys_user s ON s.id = r.student_id
WHERE r.deleted = 0

    AND r.advisor_id = #{advisorId}

ORDER BY ${sortColumn} ${sortDir}
LIMIT #{offset}, #{size}

SELECT id, advisor_id, student_id, created_at, updated_at, deleted
FROM advisor_student_relation
WHERE advisor_id = #{advisorId}
  AND student_id = #{studentId}
LIMIT 1
